<script setup lang="ts">
import {definitionTypeCaption} from './definition-presentation'
import {computed,reactive,ref,watch} from 'vue'
import {Edit,Delete} from '@element-plus/icons-vue'
import './function-definition.css'
import JsonCodeEditor from '@/ui/JsonCodeEditor.vue'
import {readCommandParameterForm,commandParameterSchema,newCommandParameter,commandParameterTypes,reconcileCommandParameterOrder,type CommandParameterForm,type CommandParameterRow} from './command-parameter-schema'
const props=withDefaults(defineProps<{modelValue:string;label:string;ariaLabel:string;disabled?:boolean;depth?:number;parameterOrder?:readonly string[]|null}>(),{depth:0})
const emit=defineEmits<{'update:modelValue':[value:string];'update:parameterOrder':[value:string[]|null]}>()
const representation=computed(()=>readCommandParameterForm(props.modelValue,props.parameterOrder)),mode=ref<'form'|'json'>(representation.value?'form':'json'),local=ref<CommandParameterForm>(representation.value||{rows:[],additionalProperties:undefined,requiredPresent:false,propertiesPresent:false,unconstrained:true})
const shown=ref(false),index=ref(-1),draft=reactive(newCommandParameter()),error=ref('')
function publish(value:string,order:string[]|null){emit('update:parameterOrder',order);emit('update:modelValue',value)}
function json(value:string){if(!props.disabled&&mode.value==='json'){try{emit('update:parameterOrder',value.trim()?reconcileCommandParameterOrder(value,props.parameterOrder):null)}catch{/* 未完成JSON保留旧顺序，保存边界会拒绝失配。 */}emit('update:modelValue',value)}}
function changeMode(value:'form'|'json'){if(props.disabled)return;if(value==='form'&&!representation.value){error.value='当前 Schema 包含表单未表示的约束，不能无损切换；请保留原 JSON 编辑。';return}shown.value=false;error.value='';mode.value=value}
function open(position=-1){if(props.disabled||mode.value!=='form')return;if(position<0&&local.value.rows.length>=100){error.value='结构化参数每份最多100项';return}index.value=position;Object.assign(draft,position<0?newCommandParameter():{...local.value.rows[position]!});error.value='';shown.value=true}
function apply(){if(props.disabled)return;try{const rows=local.value.rows.map(row=>({...row})),value={...draft,key:draft.key.trim()};if(index.value<0)rows.push(value);else rows[index.value]=value;const next={...local.value,rows,propertiesPresent:true,unconstrained:false};publish(commandParameterSchema(next),next.rows.map(row=>row.key.trim()));shown.value=false;error.value=''}catch(cause){error.value=cause instanceof Error?cause.message:'参数输入无效'}}
function remove(position:number){if(props.disabled)return;try{const next={...local.value,rows:local.value.rows.filter((_row,index)=>index!==position),propertiesPresent:true,unconstrained:false};publish(commandParameterSchema(next),next.rows.map(row=>row.key.trim()));error.value=''}catch(cause){error.value=cause instanceof Error?cause.message:'参数输入无效'}}
function extra(value:boolean){if(props.disabled)return;try{publish(commandParameterSchema({...local.value,additionalProperties:value,unconstrained:false}),local.value.rows.map(row=>row.key.trim()));error.value=''}catch(cause){error.value=cause instanceof Error?cause.message:'参数输入无效'}}
function clear(){if(props.disabled)return;shown.value=false;error.value='';publish('',null)}
function typeChanged(){draft.minimum='';draft.maximum='';draft.minLength='';draft.maxLength='';draft.minItems='';draft.maxItems='';draft.enumText='';draft.nestedSchema=''}
watch([()=>props.modelValue,()=>props.parameterOrder],()=>{const value=representation.value;if(value)local.value=value;else mode.value='json'},{flush:'pre'})
watch(()=>props.disabled,value=>{if(value)shown.value=false})
</script>
<template><div class="command-parameter-editor">
 <p v-if="!representation" class="schema-help">当前 Schema 含有表单不能完整表示的约束，保留原 JSON；不会简化、剪裁或自动重建。</p>
 <div v-if="mode==='form'"><el-table :data="local.rows" empty-text="暂无数据"><el-table-column label="参数名称"><template #default="{row}">{{row.name||'—'}}</template></el-table-column><el-table-column prop="key" label="参数标识符"/><el-table-column label="数据类型"><template #default="{row}">{{definitionTypeCaption(commandParameterTypes.find(([type])=>type===row.type)?.[1]||row.type)}}{{row.required?' · 必填':''}}</template></el-table-column><el-table-column width="130" class-name="definition-parameter-actions"><template #default="{$index}"><el-button :icon="Edit" aria-label="编辑参数" size="small" :disabled="disabled" @click="open($index)"><span class="definition-parameter-action-label">编辑参数</span></el-button><el-button :icon="Delete" aria-label="移除参数" size="small" type="danger" :disabled="disabled" @click="remove($index)"><span class="definition-parameter-action-label">移除</span></el-button></template></el-table-column></el-table><el-button size="small" :disabled="disabled||local.rows.length>=100" @click="open()">添加参数</el-button></div>
 <div v-show="mode==='json'"><JsonCodeEditor :model-value="modelValue" :ariaLabel="ariaLabel" :height="200" :disabled="disabled||mode!=='json'" @update:model-value="json"/></div>
 <details class="definition-advanced" :open="mode==='json'"><summary>高级设置</summary><div class="schema-mode"><el-button size="small" :type="mode==='form'?'primary':undefined" :disabled="disabled||!representation" @click="changeMode('form')">参数表单</el-button><el-button size="small" :type="mode==='json'?'primary':undefined" :disabled="disabled" @click="changeMode('json')">JSON 编辑</el-button><el-button size="small" :disabled="disabled||!modelValue" @click="clear">清除约束</el-button></div><el-checkbox :model-value="local.additionalProperties!==false" :disabled="disabled" @change="extra($event===true)">允许其它未声明参数</el-checkbox><p class="schema-help">名称和说明是展示元信息。Object 可编辑子字段，List 可编辑元素 Schema；联合、默认值等未表示规则请使用 JSON 编辑，保存仍由既有服务端校验。</p></details>
 <el-alert v-if="error&&!shown" :title="error" type="error" :closable="false"/>
 <el-dialog class="function-definition-dialog function-parameter-dialog" :model-value="shown&&!disabled" :title="index<0?'添加参数':'编辑参数'" width="min(700px,94vw)" append-to-body destroy-on-close :close-on-click-modal="false" @close="shown=false"><el-alert v-if="error" :title="error" type="error" :closable="false"/><el-form label-position="top" :disabled="disabled" @submit.prevent.stop="apply">
  <el-form-item label="参数名称"><el-input v-model="draft.name" :aria-label="`${label}参数名称`" maxlength="128"/></el-form-item><el-form-item label="参数标识符"><el-input v-model="draft.key" :aria-label="`${label}参数标识符`" maxlength="64"/></el-form-item><el-form-item label="数据类型"><el-select v-model="draft.type" :aria-label="`${label}参数类型`" @change="typeChanged"><el-option v-for="[value,title] in commandParameterTypes" :key="value" :value="value" :label="definitionTypeCaption(title)"/></el-select></el-form-item><el-form-item v-if="draft.type==='object'" label="对象子字段"><CommandParameterSchemaEditor v-if="depth<8" v-model="draft.nestedSchema" :label="`${label}对象子字段`" :ariaLabel="`${label}对象子Schema`" :depth="depth+1" :disabled="disabled"/><JsonCodeEditor v-else v-model="draft.nestedSchema" :ariaLabel="`${label}对象子Schema`" :disabled="disabled" :height="180"/><p class="schema-help">留空不限制对象内部字段。子字段只改变当前参数草稿，关闭外层参数时一起取消。</p></el-form-item>
  <el-form-item v-if="draft.type==='array'" label="列表元素 Schema（可选）"><JsonCodeEditor v-model="draft.nestedSchema" :ariaLabel="`${label}列表元素Schema`" :disabled="disabled" :height="180"/><p class="schema-help">填写单个元素的 Schema 对象，例如 {"type":"number"}；嵌套对象与列表沿原 Schema 校验，留空保持未限制元素类型。</p></el-form-item>
  <details class="definition-advanced" :open="draft.required||!!draft.minimum||!!draft.maximum||!!draft.minLength||!!draft.maxLength||!!draft.minItems||!!draft.maxItems||!!draft.enumText"><summary>高级设置</summary><el-form-item label="必填"><el-switch v-model="draft.required" :aria-label="`${label}参数必填`"/></el-form-item>
  <template v-if="draft.type==='number'||draft.type==='integer'"><el-form-item label="最小值（原数字）"><el-input v-model="draft.minimum" :aria-label="`${label}参数最小值`" maxlength="1024"/></el-form-item><el-form-item label="最大值（原数字）"><el-input v-model="draft.maximum" :aria-label="`${label}参数最大值`" maxlength="1024"/></el-form-item></template>
  <template v-if="draft.type==='string'"><el-form-item label="最短文本长度"><el-input v-model="draft.minLength" :aria-label="`${label}参数最短长度`" inputmode="numeric" maxlength="10"/></el-form-item><el-form-item label="最长文本长度"><el-input v-model="draft.maxLength" :aria-label="`${label}参数最长长度`" inputmode="numeric" maxlength="10"/></el-form-item></template>
  <template v-if="draft.type==='array'"><el-form-item label="最少列表项"><el-input v-model="draft.minItems" :aria-label="`${label}参数最少项`" inputmode="numeric" maxlength="10"/></el-form-item><el-form-item label="最多列表项"><el-input v-model="draft.maxItems" :aria-label="`${label}参数最多项`" inputmode="numeric" maxlength="10"/></el-form-item></template>
  <el-form-item label="枚举约束（可选 JSON 数组）"><el-input v-model="draft.enumText" :aria-label="`${label}参数枚举`" type="textarea" :rows="3" maxlength="65536"/></el-form-item></details><el-form-item label="参数描述"><el-input v-model="draft.description" :aria-label="`${label}参数说明`" type="textarea" :rows="5" maxlength="512"/></el-form-item>
 </el-form><template #footer><el-button :aria-label="`${label}取消参数`" @click="shown=false">取消</el-button><el-button type="primary" :aria-label="`${label}确定参数`" :disabled="disabled" @click="apply">保存</el-button></template></el-dialog>
</div></template>
<style scoped>.command-parameter-editor{width:100%}.schema-mode{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:8px}.schema-mode :deep(.el-button+.el-button){margin-left:0}.schema-help{color:var(--tl-muted);font-size:12px;line-height:20px;margin:8px 0}.command-parameter-editor :deep(.el-checkbox){margin-left:12px}.command-parameter-editor :deep(.el-dialog .el-select){width:100%}</style>
